import dns.zone
import dns.query
import dns.resolver

def attempt_zone_transfer(domain):
    """Try AXFR against each authoritative nameserver for the domain."""
    resolver = dns.resolver.Resolver()

    # Step 1: find the authoritative nameservers
    try:
        ns_records = resolver.resolve(domain, 'NS')
    except dns.exception.DNSException as e:
        print(f"NS lookup failed: {e}")
        return

    for ns in ns_records:
        ns_ip = str(resolver.resolve(str(ns.target), 'A')[0])
        print(f"Trying AXFR from {ns.target} ({ns_ip})...")
        try:
            # AXFR: request the full zone — misconfigured servers comply
            zone = dns.zone.from_xfr(dns.query.xfr(ns_ip, domain))
            for name, node in zone.nodes.items():
                print(f"  {name}.{domain}")
        except Exception as e:
            print(f"  Transfer refused: {e}")

attempt_zone_transfer("example.com")
